set -euo pipefail
cd /home/ubuntu/apps/travel-planner
cp /tmp/travel_answer_review.json /tmp/travel_answer_review_v2.json
echo  | base64 -d > rag/service/answer_service.py
echo  | base64 -d > rag/eval/test_answer_service.py
export PYTHONPATH=rag
.venv/bin/python -m unittest discover -s rag/eval -p test_answer_service.py -v
bash rag/service/stop_retrieval_server.sh
nohup bash rag/service/start_retrieval_server.sh > /tmp/travel-ask-deploy.log 2>&1 < /dev/null &
